public str getName()
{
    return fieldPName(InventDim, InventBatchId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventBatch inventBatch;
    while select inventBatchId from inventBatch
    {
        ret.add(inventBatch.inventBatchId);
    }
    return ret;
}

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(InventDim, inventBatchId));
        qbr.value(queryValue(_value));
    }
